						if not cdata.display_name.is_empty() and not cdata.expressions.is_empty():
							valid_chars.append(cdata)
				fname = dir.get_next()

	check("characters_ready", valid_chars.size() >= 2, "La cartella res://story/characters/ deve contenere almeno 2 risorse CharacterData con display_name ed expressions (trovate: %d)" % valid_chars.size())
